import { createClient } from '@supabase/supabase-js'
import { NextRequest, NextResponse } from 'next/server'
import { reqLang, tr } from '@/lib/serverLang'
import { verifyPassword } from '@/lib/password'
import { normalizePhone } from '@/lib/phone'
import { setSessionCookie } from '@/lib/session'
import { rateLimit } from '@/lib/rate-limit'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

export async function POST(req: NextRequest) {
  const lang = reqLang(req)
  const body = await req.json().catch(() => null)
  if (!body || typeof body !== 'object') {
    return NextResponse.json({ error: 'Invalid request.' }, { status: 400 })
  }

  const phone = normalizePhone(body.phone)
  const password = String(body.password ?? '')

  if (!phone) {
    return NextResponse.json({ error: 'Enter a valid 10-digit phone number.' }, { status: 400 })
  }
  if (!password) {
    return NextResponse.json({ error: 'Enter your password.' }, { status: 400 })
  }

  // Brute-force throttle: 5 login attempts per phone per 10 min, plus 30 / IP
  const ip = req.headers.get('x-forwarded-for')?.split(',')[0]?.trim() || 'unknown'
  if (
    !rateLimit(`login:phone:${phone}`, 5, 10 * 60 * 1000) ||
    !rateLimit(`login:ip:${ip}`, 30, 10 * 60 * 1000)
  ) {
    return NextResponse.json(
      { error: 'Too many login attempts. Please try again in a few minutes.' },
      { status: 429 },
    )
  }

  const supabase = createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!,
  )

  const { data: user, error: lookupErr } = await supabase
    .from('consumers_auth')
    .select('id, name, phone, password_hash, suspended, suspended_reason')
    .eq('phone', phone)
    .maybeSingle()

  if (lookupErr) {
    console.error('[YFF login] lookup failed:', lookupErr.code, lookupErr.message)
    if (
      lookupErr.message?.includes('does not exist')
      || lookupErr.code === '42P01'
    ) {
      return NextResponse.json(
        { error: 'consumers_auth table is missing. Run scripts/consumer-auth-migration.sql in Supabase first.' },
        { status: 500 },
      )
    }
    return NextResponse.json(
      { error: `Database error: ${lookupErr.message}` },
      { status: 500 },
    )
  }

  // Anti-enumeration: same generic error whether the phone exists or not.
  const wrongCreds = NextResponse.json(
    { error: tr(lang, 'Wrong phone or password.', 'తప్పు ఫోన్ లేదా పాస్‌వర్డ్.') },
    { status: 401 },
  )

  if (!user) return wrongCreds
  if (!user.password_hash || !verifyPassword(password, user.password_hash)) return wrongCreds

  // Suspended accounts can't sign in. Checked only after a correct password so
  // it doesn't leak which numbers are registered. The moderator's reason IS
  // shown to the consumer (per client request) so they know why; legacy
  // suspensions with no recorded reason fall back to the generic message.
  if (user.suspended === true) {
    const reason = (user.suspended_reason as string | null)?.trim() || null
    const error = reason
      ? tr(lang, `Your account has been suspended.\nReason: ${reason}\nPlease contact support.`, `మీ ఖాతా నిలిపివేయబడింది.\nకారణం: ${reason}\nదయచేసి సపోర్ట్‌ను సంప్రదించండి.`)
      : tr(lang, 'Your account has been suspended. Please contact support.', 'మీ ఖాతా నిలిపివేయబడింది. దయచేసి సపోర్ట్‌ను సంప్రదించండి.')
    // `suspended` + `suspendedReason` let the login UI render the same highlighted
    // banner the in-app header uses, instead of a plain inline error line.
    return NextResponse.json({ error, suspended: true, suspendedReason: reason }, { status: 403 })
  }

  await supabase
    .from('consumers_auth')
    .update({ last_login_at: new Date().toISOString() })
    .eq('id', user.id)

  const res = NextResponse.json({
    ok: true,
    consumer: { id: user.id, name: user.name, phone: user.phone },
  })
  try {
    setSessionCookie(res, user.id)
  } catch (e) {
    const msg = e instanceof Error ? e.message : 'Session setup failed.'
    console.error('[YFF login] setSessionCookie failed:', msg)
    return NextResponse.json({ error: msg }, { status: 500 })
  }
  return res
}

'use client'

import { useEffect, useState } from 'react'
import { useConsumerAuth } from '@/lib/ConsumerAuthContext'
import ForgotPasswordModal from '@/components/ForgotPasswordModal'
import { useLang } from '@/lib/LanguageContext'

type Mode = 'login' | 'register'

export default function AuthModal() {
  const { L } = useLang()
  const { closeAuth, login, register } = useConsumerAuth()
  const [mode, setMode] = useState<Mode>('login')
  const [name, setName] = useState('')
  const [phone, setPhone] = useState('')
  const [password, setPassword] = useState('')
  const [showPw, setShowPw] = useState(false)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState('')
  // Set when login is blocked because the account is suspended — rendered as a
  // highlighted banner (the moderator's reason) instead of a plain error line.
  const [suspended, setSuspended] = useState<{ reason: string | null } | null>(null)
  const [showForgot, setShowForgot] = useState(false)

  // Lock body scroll while modal is open
  useEffect(() => {
    const prev = document.body.style.overflow
    document.body.style.overflow = 'hidden'
    return () => { document.body.style.overflow = prev }
  }, [])

  const phoneDigits = phone.replace(/\D/g, '').slice(-10)
  const isPhoneValid = phoneDigits.length === 10
  const isPasswordValid = password.length >= 6
  const isNameValid = mode === 'login' ? true : name.trim().length > 0
  const canSubmit = !loading && isPhoneValid && isPasswordValid && isNameValid

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!canSubmit) return
    setLoading(true)
    setError('')
    setSuspended(null)
    const result = mode === 'login'
      ? await login({ phone: phoneDigits, password })
      : await register({ name: name.trim(), phone: phoneDigits, password })
    setLoading(false)
    if (!result.ok) {
      if (result.suspended) setSuspended({ reason: result.suspendedReason ?? null })
      else setError(result.error)
    }
    // On success the provider closes the modal and re-runs the queued action
  }

  return (
    <div
      className="fixed inset-0 z-[120] flex items-end sm:items-center justify-center bg-black/50"
      role="dialog"
      aria-modal="true"
      onClick={closeAuth}
    >
      <div
        className="w-full sm:max-w-md bg-white rounded-t-3xl sm:rounded-3xl shadow-xl max-h-[90vh] overflow-y-auto"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="sticky top-0 bg-white border-b border-gray-100 px-5 py-4 flex items-center justify-between">
          <h2 className="text-base font-extrabold text-gray-900 leading-tight">
            {mode === 'login' ? L('Log in', 'లాగిన్') : L('Create account', 'ఖాతా సృష్టించండి')}
          </h2>
          <button
            type="button"
            onClick={closeAuth}
            aria-label="Close"
            className="text-gray-400 text-2xl leading-none px-2 active:text-gray-600"
          >
            ×
          </button>
        </div>

        <div className="px-5 pt-3">
          <div className="grid grid-cols-2 bg-gray-100 rounded-xl p-1 text-sm font-bold">
            <button
              type="button"
              onClick={() => { setMode('login'); setError(''); setSuspended(null) }}
              className={`py-2 rounded-lg transition-colors ${
                mode === 'login' ? 'bg-white text-green-800 shadow-sm' : 'text-gray-500'
              }`}
            >
              {L('Log in', 'లాగిన్')}
            </button>
            <button
              type="button"
              onClick={() => { setMode('register'); setError(''); setSuspended(null) }}
              className={`py-2 rounded-lg transition-colors ${
                mode === 'register' ? 'bg-white text-green-800 shadow-sm' : 'text-gray-500'
              }`}
            >
              {L('Sign up', 'సైన్ అప్')}
            </button>
          </div>
        </div>

        <form className="px-5 py-4 space-y-3" onSubmit={handleSubmit}>
          {mode === 'register' && (
            <div>
              <label className="block text-xs font-semibold text-gray-700 mb-1">
                {L('Your name', 'మీ పేరు')}
              </label>
              <input
                type="text"
                autoComplete="name"
                value={name}
                onChange={(e) => setName(e.target.value)}
                placeholder="Ramu"
                maxLength={80}
                className="w-full border border-gray-200 rounded-xl px-4 py-3 text-base focus:border-green-500 focus:outline-none"
              />
            </div>
          )}

          <div>
            <label className="block text-xs font-semibold text-gray-700 mb-1">
              {L('Phone number', 'ఫోన్ నంబర్')}
            </label>
            <div className="flex items-stretch gap-2">
              <span className="flex items-center px-3 bg-gray-100 rounded-xl text-sm text-gray-600 font-semibold">
                +91
              </span>
              <input
                type="tel"
                inputMode="numeric"
                autoComplete="tel"
                value={phone}
                onChange={(e) => setPhone(e.target.value.replace(/\D/g, '').slice(0, 10))}
                placeholder="98765 43210"
                className="flex-1 border border-gray-200 rounded-xl px-4 py-3 text-base focus:border-green-500 focus:outline-none"
              />
            </div>
          </div>

          <div>
            <label className="block text-xs font-semibold text-gray-700 mb-1">
              {L('Password', 'పాస్‌వర్డ్')}
            </label>
            <div className="relative">
              <input
                type={showPw ? 'text' : 'password'}
                autoComplete={mode === 'login' ? 'current-password' : 'new-password'}
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                placeholder={mode === 'login' ? '' : 'At least 6 characters'}
                maxLength={128}
                className="w-full border border-gray-200 rounded-xl px-4 py-3 pr-16 text-base focus:border-green-500 focus:outline-none"
              />
              <button
                type="button"
                onClick={() => setShowPw((v) => !v)}
                className="absolute right-3 top-1/2 -translate-y-1/2 text-xs text-gray-500 font-semibold"
              >
                {showPw ? 'Hide' : 'Show'}
              </button>
            </div>
            {mode === 'register' && (
              <p className="text-[11px] text-gray-500 mt-1">
                {L('Minimum 6 characters', 'కనీసం 6 అక్షరాలు')}
              </p>
            )}
          </div>

          {suspended ? (
            <div className="bg-red-600 text-white rounded-xl px-4 py-3 flex items-start gap-2.5">
              <span className="text-lg leading-none mt-0.5" aria-hidden>🚫</span>
              <div className="min-w-0 flex-1">
                <p className="text-[11px] font-black uppercase tracking-wide leading-tight">
                  {L('Account suspended', 'ఖాతా నిలిపివేయబడింది')}
                </p>
                {suspended.reason && (
                  <p className="text-sm font-medium leading-snug mt-1 break-words">{suspended.reason}</p>
                )}
                <p className="text-xs text-red-100 leading-snug mt-1.5">
                  {L('Please contact support.', 'దయచేసి సపోర్ట్‌ను సంప్రదించండి.')}
                </p>
              </div>
            </div>
          ) : error ? (
            <p className="text-sm text-red-600 bg-red-50 border border-red-100 rounded-xl px-3 py-2">
              {error}
            </p>
          ) : null}

          <button
            type="submit"
            disabled={!canSubmit}
            className={`w-full font-bold py-3.5 rounded-xl text-sm ${
              canSubmit ? 'bg-green-700 text-white active:bg-green-800' : 'bg-gray-200 text-gray-500'
            }`}
          >
            {loading
              ? (mode === 'login' ? 'Logging in...' : 'Creating account...')
              : (mode === 'login' ? L('Log in', 'లాగిన్') : L('Create account', 'ఖాతా సృష్టించండి'))}
          </button>

          {mode === 'login' && (
            <button
              type="button"
              onClick={() => setShowForgot(true)}
              className="w-full text-center text-sm text-green-700 font-semibold underline"
            >
              {L('Forgot Password?', 'పాస్‌వర్డ్ మర్చిపోయారా?')}
            </button>
          )}

          <p className="text-[11px] text-gray-500 text-center pt-1 leading-relaxed">
            {mode === 'login'
              ? L('New here? Tap Sign up.', 'కొత్తవారా? సైన్ అప్ నొక్కండి.')
              : L('Already have an account? Tap Log in.', 'ఖాతా ఉందా? లాగిన్ నొక్కండి.')}
          </p>
        </form>
      </div>

      {showForgot && (
        <ForgotPasswordModal
          userType="consumer"
          initialPhone={phone}
          onClose={() => setShowForgot(false)}
          onResetComplete={() => setShowForgot(false)}
        />
      )}
    </div>
  )
}

