          userType="farmer"
          initialPhone={phone}
          onClose={() => setShowForgot(false)}
          onResetComplete={() => setShowForgot(false)}
        />
      )}
    </main>
  )
}

export default function FarmerLoginPage() {
  return (
    <Suspense fallback={null}>
      <FarmerLoginInner />
    </Suspense>
